const updatePrompt = `-- name: UpdatePrompt :exec
UPDATE image_prompts
SET name = $1,
    kind = $2,
    composition = $3,
    prompt = $4,
    updated_at = $5
WHERE id = $6
`

type UpdatePromptParams struct {
	Name        string             `json:"name"`
	Kind        string             `json:"kind"`
	Composition pgtype.Text        `json:"composition"`
	Prompt      string             `json:"prompt"`
	UpdatedAt   pgtype.Timestamptz `json:"updated_at"`
	ID          pgtype.UUID        `json:"id"`
}

func (q *Queries) UpdatePrompt(ctx context.Context, arg UpdatePromptParams) error {
	_, err := q.db.Exec(ctx, updatePrompt,
		arg.Name,
		arg.Kind,
		arg.Composition,
		arg.Prompt,
		arg.UpdatedAt,
		arg.ID,
	)
	return err
}

const updateTemplate = `-- name: UpdateTemplate :one
UPDATE templates
SET name = COALESCE($1::text, name),
    recipe = $2::jsonb,
    revision = revision + 1,
    updated_at = now()
WHERE id = $3 AND revision = $4
RETURNING revision
`

type UpdateTemplateParams struct {
	Name           pgtype.Text `json:"name"`
	Recipe         []byte      `json:"recipe"`
	ID             pgtype.UUID `json:"id"`
	ExpectRevision int64       `json:"expect_revision"`
}

// Ghi recipe (và tên nếu có) chỉ khi revision khớp — hai người lưu cùng lúc
// thì người sau nhận 0 dòng và API trả 409.
func (q *Queries) UpdateTemplate(ctx context.Context, arg UpdateTemplateParams) (int64, error) {
	row := q.db.QueryRow(ctx, updateTemplate,
		arg.Name,
		arg.Recipe,
		arg.ID,
		arg.ExpectRevision,
	)
	var revision int64
	err := row.Scan(&revision)
	return revision, err
}
